const today = new Date().toISOString().slice(0, 10);
const FEISHU_WEBHOOK = $env.N8N_01_FEISHU_WEBHOOK || 'YOUR_N8N_01_FEISHU_WEBHOOK';
const BITABLE_APP = $env.N8N_01_FEISHU_BITABLE_ID || 'YOUR_N8N_01_FEISHU_BITABLE_ID';
const BITABLE_TABLE = $env.N8N_01_FEISHU_TABLE_CLASSIC || 'YOUR_N8N_01_FEISHU_TABLE_CLASSIC';
const GITHUB_TOKEN = $env.N8N_01_GITHUB_TOKEN || '';
const startTime = Date.now();
return [{ json: { date: today, feishuWebhook: FEISHU_WEBHOOK, bitableApp: BITABLE_APP, bitableTable: BITABLE_TABLE, githubToken: GITHUB_TOKEN, startTime } }];

const config = $('初始化配置').first().json;
const GITHUB_TOKEN = config.githubToken;
const query = 'llm OR ai OR agent OR mcp OR claude OR agentic stars:>5000';
const perPage = 100;
const totalPages = 5;
let allItems = [];

for (let page = 1; page <= totalPages; page++) {
    const url = 'https://api.github.com/search/repositories?q=' + encodeURIComponent(query) + '&sort=stars&order=desc&per_page=' + perPage + '&page=' + page;
    try {
        const resp = await this.helpers.httpRequest({
            method: 'GET', url: url,
            headers: { 'Authorization': 'Bearer ' + GITHUB_TOKEN, 'Accept': 'application/vnd.github.v3+json' },
            timeout: 30000
        });
        const items = resp.items || [];
        allItems = allItems.concat(items);
        if (items.length < perPage) break;
    } catch (e) {
        console.log('GitHub API 第' + page + '页失败: ' + e.message);
        break;
    }
}

return [{ json: { data: { items: allItems, total_count: allItems.length }, statusCode: 200 } }];

const resp = $input.first().json;
const config = $('初始化配置').first().json;

// 直接透传原始数据，分类逻辑移到经典去重节点
return [{ json: {
    data: resp.data || {},
    statusCode: resp.statusCode || 200,
    date: config.date,
    feishuWebhook: config.feishuWebhook,
    bitableApp: config.bitableApp,
    bitableTable: config.bitableTable,
    startTime: config.startTime
} }];

const data = $input.first().json;
const items = data.items || [];

if (items.length === 0) {
    return [{ json: { ...data, translationOk: true, translatedCount: 0, totalToTranslate: 0 } }];
}

const descs = items.map(i => (i.description || '').substring(0, 150)).filter(d => d.length > 10 && /[a-zA-Z]/.test(d));

if (descs.length === 0) {
    return [{ json: { ...data, translationOk: true, translatedCount: 0, totalToTranslate: 0 } }];
}

const translatedMap = {};
const batchSize = 10;

for (let i = 0; i < descs.length; i += batchSize) {
    const batch = descs.slice(i, i + batchSize);
    const prompt = '将以下' + batch.length + '个项目描述翻译成中文。简短，每条一行。\n' + batch.map((d, idx) => (idx+1) + '. ' + d).join('\n');

    try {
        const resp = await this.helpers.httpRequest({
            method: 'POST', url: 'http://192.168.31.87:11434/v1/chat/completions',
            headers: { 'Content-Type': 'application/json' },
            body: { model: 'qwen2.5:3b', messages: [{ role: 'system', content: '你是项目描述翻译助手。' }, { role: 'user', content: prompt }], temperature: 0.1, max_tokens: 1500, stream: false },
            timeout: 120000
        });
        const content = resp.choices?.[0]?.message?.content || '';
        const lines = content.split('\n').map(l => l.replace(/^\d+[\.\s]+/, '').trim()).filter(l => l.length > 0);
        const matchCount = Math.min(batch.length, lines.length);
        for (let j = 0; j < matchCount; j++) {
            if (lines[j]) translatedMap[batch[j]] = lines[j];
        }
    } catch (e) {
        console.log('翻译失败: ' + e.message);
    }
}

items.forEach(item => {
    const desc = (item.description || '').substring(0, 150);
    if (translatedMap[desc]) {
        item.descriptionCn = translatedMap[desc];
    }
});

return [{ json: { ...data, translationOk: true, translatedCount: Object.keys(translatedMap).length, totalToTranslate: descs.length } }]

const data = $input.first().json;
const items = data.items || [];

if (items.length === 0) {
    return [{ json: { ...data, writeCount: 0, tokenOk: true } }];
}

const APP_ID = $env.N8N_01_FEISHU_APP_ID || '';
const APP_SECRET = $env.N8N_01_FEISHU_APP_SECRET || '';
const TABLE_ID = data.bitableTable;

let token = '';
try {
