let md = '📊 **经典项目概览**\n';
md += '· 新发现: **' + items.length + '** 个 · 写入: ' + (writeOk ? '✅ ' + writeCount : '❌ 失败') + '\n';
md += '· 翻译: ' + (transOk ? '✅ ' + transCount + '/' + transTotal : '❌') + ' · 跳过重复: ' + dedupSkipped + '\n';
md += '· 耗时: ' + elapsedStr + '\n\n';

if (items.length > 0) {
    const tier1 = items.filter(i => i.stars >= 50000);
    const tier2 = items.filter(i => i.stars >= 20000 && i.stars < 50000);
    const tier3 = items.filter(i => i.stars < 20000);

    if (tier1.length > 0) {
        md += '**👑 超级巨星** (' + tier1.length + '个)\n';
        tier1.forEach((item, i) => {
            const desc = item.descriptionCn || item.description || '';
            md += (i+1) + '. [' + item.name + '](' + item.url + ') ⭐' + (item.stars/1000).toFixed(0) + 'k\n';
            if (desc) md += '   ' + desc.substring(0, 60) + '\n';
        });
        md += '\n';
    }
    if (tier2.length > 0) {
        md += '**🌟 顶级项目** (' + tier2.length + '个)\n';
        tier2.forEach((item, i) => {
            const desc = item.descriptionCn || item.description || '';
            md += (i+1) + '. [' + item.name + '](' + item.url + ') ⭐' + (item.stars/1000).toFixed(0) + 'k\n';
            if (desc) md += '   ' + desc.substring(0, 60) + '\n';
        });
        md += '\n';
    }
    if (tier3.length > 0) {
        md += '**⭐ 热门项目** (' + tier3.length + '个)\n';
        tier3.forEach((item, i) => {
            const desc = item.descriptionCn || item.description || '';
            md += (i+1) + '. [' + item.name + '](' + item.url + ') ⭐' + item.stars + '\n';
            if (desc) md += '   ' + desc.substring(0, 60) + '\n';
        });
    }
} else {
    md += '暂无新发现的项目';
}

const payload = {
    msg_type: 'interactive',
    card: {
        schema: '2.0',
        config: { wide_screen_mode: true },
        header: {
            title: { tag: 'plain_text', content: '📊 经典 AI 项目 ' + date },
            template: 'blue'
        },
        body: { elements: [{ tag: 'markdown', content: md }] }
    }
};

try {
    await this.helpers.httpRequest({ method: 'POST', url: feishuWebhook, headers: { 'Content-Type': 'application/json' }, body: payload, timeout: 10000 });
